head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07400";
scwin.form = null;
scwin.dts_List = null;
scwin.dts_Cod = null;
scwin.saveYn = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.dts_Cod = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Cod')) : $c.util.getComponent('dts_Cod');
        scwin.saveYn = '' + dma_dataList.get("save_yn") + '';
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07400.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_dataList.get("bodResolDd")); } },
        { childId: "__rb1", attr: "label", fn: function () { return String(dma_dataList.get("prelmInvstgBillSubmitDd")); } },
        { childId: "__rb2", attr: "label", fn: function () { return String(dma_dataList.get("shrhdFinalDd")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_dataList.get("genmeetHldDd")); } },
        { childId: "__rb4", attr: "label", fn: function () { return String(dma_dataList.get("stkBidClmExerStrtDd")) + " ~ " + String(dma_dataList.get("stkBidClmExerEndDd")) + " 가격 : " + String(dma_dataList.get("stkBidClmExerPrc")); } },
        { childId: "__rb5", attr: "label", fn: function () { return String(dma_dataList.get("mergeDd")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.onload();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07400.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_print_onclick
 * @description btn_print 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = async function(e){
    try {
        await $c.win.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07400.btn_print_onclick' }); }
};

/**
 * @method
 * @name ipt_isuShrs0_onclick
 * @description ipt_isuShrs0 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuShrs0_onclick = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.select()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07400.ipt_isuShrs0_onclick' }); }
};

/**
 * @method
 * @name ipt_isuShrs0_onkeyup
 * @description ipt_isuShrs0 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_isuShrs0_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        (selfVar.value = $c.num.formatNumber(selfVar.value));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07400.ipt_isuShrs0_onkeyup' }); }
};

